package com.cpf.education.online.common.controller;
import com.cpf.education.online.common.service.MemberReferenceService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.web.api.CpfController;import io.swagger.v3.oas.annotations.Operation;import java.time.LocalDate;import java.util.Map;import org.springframework.web.bind.annotation.*;
/** 공통정보 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfController @RequestMapping("/edu/online/common") public class MemberReferenceController {private final MemberReferenceService service;public MemberReferenceController(MemberReferenceService s){service=s;}@GetMapping @Operation(operationId="EDU_COMMON_REFERENCE",summary="코드·메시지·파라미터·영업일") @CpfOnlineTransaction(operationId="EDU_COMMON_REFERENCE",name="공통정보 사용 거래",description="CPF Common Code/Message/Parameter/Calendar API를 함께 사용한다.") public Map<String,Object> resolve(@RequestParam String status,@RequestParam String date){return service.resolve(status,LocalDate.parse(date));}}
